const b = ($json && $json.body) ? $json.body : $json;
return { json: {
  contact_id:        String(b.contact_id || '').trim(),
  instantly_lead_id: String(b['Instantly Lead Id'] || b.instantly_lead_id || '').trim(),
  email:             String(b.email || '').trim(),
  // opp context resolved by the dispatcher (accept either naming)
  opp_id:      String(b.opp_id      || b.matched_opp_id      || '').trim(),
  pipeline_id: String(b.pipeline_id || b.matched_pipeline_id || '').trim(),
  stage_id:    String(b.stage_id    || b.matched_stage_id    || '').trim(),
  outcome: 'no answer'
}};

const r = $('GHL: Get Contact').item.json;
const c = (r.contacts && r.contacts[0]) ? r.contacts[0] : (r.contact || r);
const cf = id => { const f = (c.customFields || []).find(x => x.id === id); return f ? f.value : ''; };

const EVENTLOGS_ID='7D9N71mEDfipN90zfV0j', LEADID_ID='TWLomDBX0XInU1IKrG8L';

const CALL_PIPELINE  = '9E6y34DlG1Imr8FV42RV';   // Cold Outbound Call Pipeline
const EMAIL_PIPELINE = '1A1RkYaL93s2rqbQ3Opi';   // Cold Outbound Email Pipeline

// caller opp + its stage come from the dispatcher (no re-search / re-derivation)
const caller_opp_id = String($('Normalize').item.json.opp_id   || '').trim();
const cur_stage     = String($('Normalize').item.json.stage_id || '').trim();

// stage id -> human name (event log context)
const STAGE_NAME = {
  '060f44a8-4cd8-4561-8c84-7150bfd57498': 'Day 1 Call A',
  '04ccf8e0-383f-4c17-9268-51020233d08b': 'Day 1 Call A (MGR)',
  'cb2dc70f-c44e-48fd-b9cc-438901e292ac': 'Day 1 Call A (from on hold)',
  '4cb90aaa-b8c3-40a8-b1e6-6585213b258c': 'Day 1 Call B',
  '648c4952-1ac0-4c8c-9e52-b93efa5ec39e': 'Day 1 Call B (MGR)',
  '4b1d7a88-87c0-422b-90e4-b48d16430900': 'Day 2 Call',
  '4b3023aa-515b-40f8-ad82-292ca685562e': 'Day 2 Call (MGR)',
  'ab6ae288-8886-4d4e-ba61-2d6134f585bd': 'Day 2 Call (from on hold)',
  '40bdc040-8e97-4654-ae52-51e458c7f882': 'Day 2 Call (missed call)',
  '59069dd4-8071-45e2-820c-df565ab17132': 'Day 2 Call MGR (missed call)',
  'f8407fb8-f94c-4443-baf9-b7d1c6f50d34': 'Day 3 Call',
  '5bfcb041-6abb-48d2-a60d-511af1af807f': 'Day 3 Call (MGR)',
  '1bd6fb3c-b7bb-40bd-af31-f1c62065c7bb': 'Day 3 Call (from on hold)',
  'b50e0792-a88c-4d0a-9e44-2d5cebfdef18': 'Day 3 Call (missed call)',
  '21b772e5-385d-47b7-8234-3138bd312a26': 'Day 3 Call MGR (missed call)',
  'e4b13f51-2229-4d47-aa3e-12381a31a8c1': 'Cold Email 2',
  '342b193f-9456-4bcc-a2a7-cb81973500c9': 'Cold Email 3',
  'f3ea4cd2-daf2-4ca2-baaa-301f807d697c': 'Cold Email 4'
};

// (1) SAME-DAY REDIAL: a missed Day 1 Call A stays in the CALL pipeline and re-dials as Call B.
const REDIAL_TO = {
  '060f44a8-4cd8-4561-8c84-7150bfd57498': '4cb90aaa-b8c3-40a8-b1e6-6585213b258c', // D1 Call A                -> D1 Call B
  'cb2dc70f-c44e-48fd-b9cc-438901e292ac': '4cb90aaa-b8c3-40a8-b1e6-6585213b258c', // D1 Call A (from on hold) -> D1 Call B
  '04ccf8e0-383f-4c17-9268-51020233d08b': '648c4952-1ac0-4c8c-9e52-b93efa5ec39e'  // D1 Call A (MGR)          -> D1 Call B (MGR)
};

// (2) OTHERWISE: hand the opp off to the EMAIL pipeline at Send Cold Email N+1.
const STAGE_TO_N = {
  '4cb90aaa-b8c3-40a8-b1e6-6585213b258c': 1, // Day 1 Call B
  '648c4952-1ac0-4c8c-9e52-b93efa5ec39e': 1, // Day 1 Call B (MGR)
  '4b1d7a88-87c0-422b-90e4-b48d16430900': 2, // Day 2 Call
  '4b3023aa-515b-40f8-ad82-292ca685562e': 2, // Day 2 Call (MGR)
  'ab6ae288-8886-4d4e-ba61-2d6134f585bd': 2, // Day 2 Call (from on hold)
  '40bdc040-8e97-4654-ae52-51e458c7f882': 2, // Day 2 Call (missed call)
  '59069dd4-8071-45e2-820c-df565ab17132': 2, // Day 2 Call MGR (missed call)
  'f8407fb8-f94c-4443-baf9-b7d1c6f50d34': 3, // Day 3 Call
  '5bfcb041-6abb-48d2-a60d-511af1af807f': 3, // Day 3 Call (MGR)
  '1bd6fb3c-b7bb-40bd-af31-f1c62065c7bb': 3, // Day 3 Call (from on hold)
  'b50e0792-a88c-4d0a-9e44-2d5cebfdef18': 3, // Day 3 Call (missed call)
  '21b772e5-385d-47b7-8234-3138bd312a26': 3  // Day 3 Call MGR (missed call)
};
const SEND_NEXT = { 1:'e4b13f51-2229-4d47-aa3e-12381a31a8c1', 2:'342b193f-9456-4bcc-a2a7-cb81973500c9', 3:'f3ea4cd2-daf2-4ca2-baaa-301f807d697c' };

// (3) MISSED-CALL EMAIL: independent of N. MCE1 = first miss of Day 1 or Day 2.
//     MCE2 = second miss of Day 2 (i.e. the lead is already in a Day 2 'missed call' stage).
//     Everything else (Day 1 Call B, all of Day 3) sends no missed-call email.
const MCE_BY_STAGE = {
  '060f44a8-4cd8-4561-8c84-7150bfd57498': 1, // Day 1 Call A
  '04ccf8e0-383f-4c17-9268-51020233d08b': 1, // Day 1 Call A (MGR)
  'cb2dc70f-c44e-48fd-b9cc-438901e292ac': 1, // Day 1 Call A (from on hold)
  '4b1d7a88-87c0-422b-90e4-b48d16430900': 1, // Day 2 Call
  '4b3023aa-515b-40f8-ad82-292ca685562e': 1, // Day 2 Call (MGR)
  'ab6ae288-8886-4d4e-ba61-2d6134f585bd': 1, // Day 2 Call (from on hold)
  '40bdc040-8e97-4654-ae52-51e458c7f882': 2, // Day 2 Call (missed call)
  '59069dd4-8071-45e2-820c-df565ab17132': 2  // Day 2 Call MGR (missed call)
};
const INTEREST = { 1:-29996, 2:-29992 };

const redial_stage_id = REDIAL_TO[cur_stage] || '';
const is_redial = !!redial_stage_id;

const N = is_redial ? 0 : (STAGE_TO_N[cur_stage] || 0);

const target_pipeline_id = is_redial ? CALL_PIPELINE : EMAIL_PIPELINE;
const target_stage_id    = is_redial ? redial_stage_id : (SEND_NEXT[N] || '');
const can_move = !!(caller_opp_id && target_stage_id);

const mce = MCE_BY_STAGE[cur_stage] || 0;
const interest_value = INTEREST[mce] || 0;   // 0 => no missed-call email
const sends_email = interest_value !== 0;

const now = DateTime.now().setZone('America/Los_Angeles');
const stampNew = now.toFormat('ccc, LLL d, yyyy, hh:mm a') + ' (PT)';

const from_stage_name = STAGE_NAME[cur_stage] || ('unknown stage' + (cur_stage ? ' ' + cur_stage : ''));
const to_stage_name   = STAGE_NAME[target_stage_id] || '';

// event log: '[stamp] <stage name> no answer'
const elBase  = String(cf(EVENTLOGS_ID) || '').trim();
const elEntry = '[' + stampNew + '] ' + from_stage_name + ' no answer';
const updated_event_logs = elBase ? (elBase + '\n' + elEntry) : elEntry;

return { json: {
  contact_id: String(c.id || $('Normalize').item.json.contact_id || '').trim(),
  caller_opp_id,
  target_pipeline_id, target_stage_id, can_move, is_redial,
  from_stage_name, to_stage_name,
  N, mc: String(mce || ''), interest_value, sends_email,
  updated_event_logs,
  instantly_lead_id: String(cf(LEADID_ID) || $('Normalize').item.json.instantly_lead_id || '').trim(),
  first_name: String(c.firstName || '').trim()
}};
